/*! igtc-language-role-bridge.min.js (cleaned) */
(function(){
  'use strict';
  var LANG_ALIAS={'ko-kr':'ko','en-us':'en','zh-cn':'zh'};
  window.normalizeLang=function(code){
    if(!code) return 'en';
    code=code.toLowerCase();
    if(LANG_ALIAS[code]) return LANG_ALIAS[code];
    if(code.includes('-')) return code.split('-')[0];
    return code;
  };
  window.getUserRole=function(){
    try { return localStorage.getItem('user_role')||'guest'; }
    catch(_){ return 'guest'; }
  };
})();

/* IGDC/MARU common empty-slot state: loaded once, before every hub renderer. */
(function(global){
  'use strict';
  if (global.IGDCSlotState) return;
  var COPY={
    ar:'يتم إعداد المحتوى.',bn:'কনটেন্ট প্রস্তুত করা হচ্ছে।',de:'Inhalte werden vorbereitet.',en:'Content is being prepared.',
    es:'El contenido está en preparación.',fa:'محتوا در حال آماده‌سازی است.',fr:'Le contenu est en cours de préparation.',hi:'सामग्री तैयार की जा रही है।',
    hu:'A tartalom előkészítés alatt áll.',id:'Konten sedang disiapkan.',it:'Il contenuto è in preparazione.',ja:'コンテンツを準備中です。',
    ko:'콘텐츠를 준비하고 있습니다.',ms:'Kandungan sedang disediakan.',nl:'De inhoud wordt voorbereid.',pl:'Treść jest przygotowywana.',
    pt:'O conteúdo está sendo preparado.',ru:'Контент готовится.',sv:'Innehållet förbereds.',sw:'Maudhui yanaandaliwa.',
    ta:'உள்ளடக்கம் தயாராகிக் கொண்டிருக்கிறது.',th:'กำลังเตรียมเนื้อหาอยู่',tl:'Inihahanda ang nilalaman.',tr:'İçerik hazırlanıyor.',
    uk:'Вміст готується.',ur:'مواد تیار کیے جا رہے ہیں۔',uz:'Kontent tayyorlanmoqda.',vi:'Nội dung đang được chuẩn bị.',
    zh:'内容正在准备中。',zht:'內容正在準備中。'
  };
  var PLACEHOLDER=/^(?:coming\s+soon|content\s+is\s+being\s+prepared\.?|auto-filled|loading|preparing|right\s+sample|tour\s+brand\s+\d+|recommended(?:\s+brand)?\s*\d*|product\s+item\s*\d*|recommend\s+item\s*\d*|new\s+item\s*\d*|trending\s+item\s*\d*|special\s+item\s*\d*|sponsor\s+item\s*\d*)$/i;
  function language(){
    var raw='';
    try{ raw=(document.documentElement&&document.documentElement.getAttribute('lang')) || ''; }catch(_e){}
    raw=String(raw||'en').trim().toLowerCase().replace(/_/g,'-');
    if(raw==='zh-tw'||raw==='zh-hk'||raw==='zh-mo'||raw.indexOf('zh-hant')===0||raw==='zht'||raw.indexOf('zht-')===0) return 'zht';
    if(raw==='zh-cn'||raw==='zh-sg'||raw.indexOf('zh-hans')===0) return 'zh';
    raw=raw.split('-')[0];
    return COPY[raw] ? raw : 'en';
  }
  function text(){ return COPY[language()] || COPY.en; }
  function direction(){ var l=language(); return (l==='ar'||l==='fa'||l==='ur')?'rtl':'ltr'; }
  function isPlaceholderText(value){ return PLACEHOLDER.test(String(value||'').replace(/\s+/g,' ').trim()); }
  function installStyle(){
    if(document.getElementById('igdc-slot-state-style-v2')) return;
    var s=document.createElement('style'); s.id='igdc-slot-state-style-v2';
    s.textContent='.igdc-slot-state-card{display:flex;align-items:center;justify-content:center;min-height:72px;box-sizing:border-box;padding:14px;border:1px dashed rgba(104,117,136,.38);border-radius:12px;background:linear-gradient(135deg,rgba(246,248,251,.96),rgba(238,242,247,.96));color:#5f6b7a;text-align:center;font-size:.93rem;line-height:1.5}.thumb-card[data-igdc-slot-state="preparing"] .thumb-img,.card[data-igdc-slot-state="preparing"] .thumb,.ad-box[data-igdc-slot-state="preparing"] img{background:linear-gradient(135deg,#eef2f6,#dfe7ef)!important}.igdc-slot-media-failed{position:relative!important;display:flex!important;align-items:center!important;justify-content:center!important;min-height:72px!important;background:linear-gradient(135deg,#eef2f6,#dfe7ef)!important;color:#5f6b7a!important;overflow:hidden!important}.igdc-slot-media-failed>img{display:none!important}.igdc-slot-media-failed .igdc-slot-media-failed-label{display:block!important;padding:10px;text-align:center;font-size:.82rem;line-height:1.35}[data-igdc-slot-state="preparing"]{cursor:default!important}';
    (document.head||document.documentElement).appendChild(s);
  }
  function labelTarget(node){
    if(!node || node.nodeType!==1) return node;
    if(node.classList && node.classList.contains('igdc-slot-state-card')) return node;
    return node.querySelector('.meta,.thumb-title,.title,.tour-card-title,.ad-title,.card-title,.card-name,.card-meta,[data-igdc-slot-label]') || node;
  }
  function sync(node){
    if(!node || node.nodeType!==1) return;
    var target=labelTarget(node);
    var current=String(target.textContent||'').replace(/\s+/g,' ').trim();
    if(node.getAttribute('data-igdc-slot-state')==='preparing' || !current || isPlaceholderText(current)){
      target.textContent=text();
      node.setAttribute('data-igdc-slot-state','preparing');
      node.setAttribute('aria-busy','true');
      node.setAttribute('dir',direction());
    }
  }
  function syncKnown(root){
    var scope=root||document;
    if(scope.nodeType===1 && scope.matches && scope.matches('[data-placeholder="true"],[data-dummy="1"],.thumb-card--seed,[data-igdc-slot-state="preparing"]')) sync(scope);
    var list=scope.querySelectorAll ? scope.querySelectorAll('[data-placeholder="true"],[data-dummy="1"],.thumb-card--seed,[data-igdc-slot-state="preparing"]') : [];
    for(var i=0;i<list.length;i++) sync(list[i]);
  }
  function hasActualContent(host){
    if(!host || !host.querySelectorAll) return false;
    var nodes=host.querySelectorAll('a,article,.card,.thumb-card,.ad-box,.donation-card,.shop-card');
    for(var i=0;i<nodes.length;i++){
      var n=nodes[i];
      if(n.getAttribute('data-igdc-slot-state')==='preparing'||n.getAttribute('data-placeholder')==='true'||n.getAttribute('data-dummy')==='1') continue;
      var copy=String(n.textContent||'').replace(/\s+/g,' ').trim();
      var visual=!!n.querySelector('img[src],video,iframe,[style*="background-image"]');
      if((copy&&!isPlaceholderText(copy))||visual) return true;
    }
    return false;
  }
  function mountIfEmpty(host,options){
    if(!host || hasActualContent(host)) return null;
    var existing=host.querySelector && host.querySelector('[data-igdc-slot-state="preparing"]');
    if(existing){ sync(existing); return existing; }
    options=options||{};
    var node=document.createElement(options.tagName||'div');
    node.className=(options.className?options.className+' ':'')+'igdc-slot-state-card';
    node.setAttribute('data-igdc-slot-state','preparing'); node.setAttribute('role','status'); node.setAttribute('aria-live','polite'); node.setAttribute('aria-busy','true'); node.setAttribute('dir',direction()); node.textContent=text();
    host.appendChild(node); return node;
  }
  function markImageFailure(image){
    if(!image || image.dataset.igdcSlotFailureHandled==='1') return;
    image.dataset.igdcSlotFailureHandled='1';
    var card=image.closest&&image.closest('[data-psom-key],.thumb-card,.media-card,.shop-card,.ad-box,.donation-card,.card');
    if(!card) return;
    var media=image.closest('.thumb,.thumb-img,.pic,.card-img,.image,figure')||image.parentElement;
    if(!media) return;
    media.classList.add('igdc-slot-media-failed'); media.setAttribute('aria-label',text());
    var label=media.querySelector('.igdc-slot-media-failed-label');
    if(!label){ label=document.createElement('span'); label.className='igdc-slot-media-failed-label'; media.appendChild(label); }
    label.textContent=text();
  }
  function bindImageFallback(){
    document.addEventListener('error',function(e){ var t=e.target; if(t&&String(t.tagName||'').toUpperCase()==='IMG') markImageFailure(t); },true);
  }
  global.IGDCSlotState={version:'v2.0.0',language:language,text:text,isPlaceholderText:isPlaceholderText,syncKnownPlaceholders:syncKnown,mountIfEmpty:mountIfEmpty,markImageFailure:markImageFailure};
  installStyle(); bindImageFallback();
  function sweep(){ installStyle(); syncKnown(document); }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',sweep,{once:true}); else sweep();
  global.addEventListener('igdc:feed:ready',sweep); global.addEventListener('load',sweep,{once:true});
})(window);
